CREATE OR REPLACE FUNCTION public.assign_demo_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  demo_org_id uuid;
BEGIN
  -- Handle admin demo account
  IF NEW.email = 'admin@demo.sigma' THEN
    INSERT INTO public.user_roles (user_id, role)
    VALUES (NEW.id, 'admin')
    ON CONFLICT (user_id) DO UPDATE SET role = 'admin';
  END IF;

  -- Handle organization demo account
  IF NEW.email = 'org@demo.sigma' THEN
    -- First create/find the demo organization
    SELECT id INTO demo_org_id FROM public.organizations WHERE name = 'Демо Организация';

    IF demo_org_id IS NULL THEN
      INSERT INTO public.organizations (name, email)
      VALUES ('Демо Организация', 'org@demo.sigma')
      RETURNING id INTO demo_org_id;
    END IF;

    -- Assign organization role
    INSERT INTO public.user_roles (user_id, role)
    VALUES (NEW.id, 'organization')
    ON CONFLICT (user_id) DO UPDATE SET role = 'organization';

    -- Update profile with organization_id
    UPDATE public.profiles 
    SET organization_id = demo_org_id
    WHERE user_id = NEW.id;
  END IF;

  -- Handle student demo account - just ensure student role (default)
  IF NEW.email = 'student@demo.sigma' THEN
    INSERT INTO public.user_roles (user_id, role)
    VALUES (NEW.id, 'student')
    ON CONFLICT (user_id) DO UPDATE SET role = 'student';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.log_org_staff_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE actor_name TEXT;
BEGIN
  SELECT COALESCE(full_name, email) INTO actor_name FROM public.profiles WHERE user_id = auth.uid() LIMIT 1;
  IF (TG_OP = 'INSERT') THEN
    INSERT INTO public.role_audit_log (scope, organization_id, target_user_id, action, new_role, new_sections_access, performed_by, performed_by_name)
    VALUES ('organization', NEW.organization_id, NEW.user_id, 'granted', NEW.role, NEW.sections_access, auth.uid(), actor_name);
    RETURN NEW;
  ELSIF (TG_OP = 'UPDATE') THEN
    IF (OLD.role IS DISTINCT FROM NEW.role) OR (OLD.sections_access IS DISTINCT FROM NEW.sections_access) THEN
      INSERT INTO public.role_audit_log (scope, organization_id, target_user_id, action, old_role, new_role, old_sections_access, new_sections_access, performed_by, performed_by_name)
      VALUES ('organization', NEW.organization_id, NEW.user_id, 'changed', OLD.role, NEW.role, OLD.sections_access, NEW.sections_access, auth.uid(), actor_name);
    END IF;
    RETURN NEW;
  ELSIF (TG_OP = 'DELETE') THEN
    INSERT INTO public.role_audit_log (scope, organization_id, target_user_id, action, old_role, old_sections_access, performed_by, performed_by_name)
    VALUES ('organization', OLD.organization_id, OLD.user_id, 'revoked', OLD.role, OLD.sections_access, auth.uid(), actor_name);
    RETURN OLD;
  END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.sync_org_staff_to_sales_managers()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE u uuid; users uuid[]; v_name text;
BEGIN
  IF TG_OP='DELETE' THEN users:=ARRAY[OLD.user_id];
  ELSIF TG_OP='UPDATE' THEN users:=ARRAY[OLD.user_id,NEW.user_id];
  ELSE users:=ARRAY[NEW.user_id]; END IF;
  FOR u IN SELECT DISTINCT x FROM unnest(users)x WHERE x IS NOT NULL LOOP
    IF public.has_role('admin'::public.app_role,u)
       OR public.has_role('sales_manager'::public.app_role,u)
       OR EXISTS(SELECT 1 FROM public.admin_staff a WHERE a.user_id=u
                 AND a.role IN('sales_manager','admin','super_admin')) THEN
      CONTINUE;
    END IF;
    v_name:=NULL;
    SELECT COALESCE(NULLIF(s.display_name,''),NULLIF(p.full_name,''),p.email,'Сотрудник')
      INTO v_name FROM public.org_staff s LEFT JOIN public.profiles p ON p.user_id=s.user_id
     WHERE s.user_id=u AND (s.can_receive_crm_tasks OR s.role='sales_manager')
       AND (s.expires_at IS NULL OR s.expires_at>now())
       AND NOT EXISTS(SELECT 1 FROM public.account_deletion_revocations r WHERE r.user_id=u)
     ORDER BY s.organization_id LIMIT 1;
    IF v_name IS NOT NULL THEN
      INSERT INTO public.sales_managers(user_id,full_name,is_active) VALUES(u,v_name,true)
      ON CONFLICT(user_id) DO UPDATE SET full_name=EXCLUDED.full_name,is_active=true;
    ELSE
      UPDATE public.sales_managers SET is_active=false WHERE user_id=u;
    END IF;
  END LOOP;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$
